INSERT INTO ITEM (ITEM_CODE, ITEM_NAME, DESCRIPTION, PRICE, STOCK_QUANTITY, STATUS, IMAGE_URL, CREATED_DATE) VALUES 
('ITEM-001', '노트북 스탠드', '노트북을 더 편안하게 사용할 수 있는 각도 조절 스탠드입니다. 알루미늄 소재로 제작되어 견고하고 가벼우며, 통풍이 잘 되어 발열을 줄여줍니다.', 50000, 50, 'ACTIVE', '', TIMESTAMP '2024-01-01 10:00:00'),
('ITEM-002', '무선 마우스', '블루투스 5.0 무선 마우스입니다. 긴 배터리 수명과 정밀한 센서로 게이밍과 업무에 모두 적합합니다.', 50000, 30, 'ACTIVE', '', TIMESTAMP '2024-01-02 11:00:00'),
('ITEM-003', '키보드', '기계식 키보드로 타이핑의 쾌감을 제공합니다. RGB 백라이트와 다양한 스위치 옵션을 제공합니다.', 89000, 25, 'ACTIVE', '', TIMESTAMP '2024-01-03 12:00:00'),
('ITEM-004', '모니터 27인치', '4K UHD 해상도를 지원하는 27인치 모니터입니다. IPS 패널로 넓은 시야각과 정확한 색감을 제공합니다.', 250000, 15, 'ACTIVE', '', TIMESTAMP '2024-01-04 13:00:00'),
('ITEM-005', 'HDMI 케이블', '고속 데이터 전송을 지원하는 프리미엄 HDMI 케이블입니다. 4K 60Hz를 완벽하게 지원합니다.', 35000, 100, 'ACTIVE', '', TIMESTAMP '2024-01-05 14:00:00'),
('ITEM-006', 'USB 허브', 'USB 3.0을 지원하는 7포트 허브입니다. 빠른 데이터 전송 속도와 안정적인 전원 공급을 제공합니다.', 25000, 80, 'ACTIVE', '', TIMESTAMP '2024-01-06 15:00:00'),
('ITEM-007', '케이블 정리함', '다양한 케이블을 깔끔하게 정리할 수 있는 정리함입니다. 벨크로 스트랩과 분리형 구획으로 효율적인 관리가 가능합니다.', 50000, 40, 'ACTIVE', '', TIMESTAMP '2024-01-07 16:00:00'),
('ITEM-008', '웹캠', '4K 해상도를 지원하는 고화질 웹캠입니다. 자동 초점과 노이즈 제거 기능으로 선명한 화질을 제공합니다.', 120000, 20, 'ACTIVE', '', TIMESTAMP '2024-01-08 17:00:00'),
('ITEM-009', '마이크', 'USB 연결 방식의 콘덴서 마이크입니다. 스튜디오급 음질로 녹음과 방송에 최적화되어 있습니다.', 90000, 35, 'ACTIVE', '', TIMESTAMP '2024-01-09 18:00:00'),
('ITEM-010', '스피커', '2.1채널 스피커 시스템입니다. 강력한 베이스와 선명한 고음으로 몰입감 있는 사운드를 제공합니다.', 175000, 18, 'ACTIVE', '', TIMESTAMP '2024-01-10 19:00:00'),
('ITEM-011', '헤드셋', '노이즈 캔슬링 기능이 있는 무선 헤드셋입니다. 30시간 배터리 수명과 편안한 착용감을 제공합니다.', 95000, 22, 'ACTIVE', '', TIMESTAMP '2024-01-11 20:00:00'),
('ITEM-012', '태블릿', '10.9인치 디스플레이를 가진 태블릿입니다. 강력한 프로세서와 긴 배터리 수명으로 생산성과 엔터테인먼트를 모두 만족시킵니다.', 280000, 12, 'ACTIVE', '', TIMESTAMP '2024-01-12 21:00:00'),
('ITEM-013', '스마트폰 케이스', '강화 유리 소재의 투명 케이스입니다. 얇으면서도 충격에 강해 스마트폰을 안전하게 보호합니다.', 45000, 150, 'ACTIVE', '', TIMESTAMP '2024-01-13 22:00:00'),
('ITEM-014', '보호필름', '강화 유리 소재의 화면 보호필름입니다. 지문 방지 코팅과 높은 투명도로 화질 저하 없이 화면을 보호합니다.', 45000, 200, 'ACTIVE', '', TIMESTAMP '2024-01-14 23:00:00'),
('ITEM-015', '충전기', '고속 충전을 지원하는 USB-C 충전기입니다. 다양한 기기와 호환되며 안전한 충전을 보장합니다.', 35000, 120, 'ACTIVE', '', TIMESTAMP '2024-01-15 10:00:00'),
('ITEM-016', '케이블', 'USB-C to USB-C 케이블입니다. 빠른 데이터 전송과 충전을 지원하며 내구성이 뛰어납니다.', 25000, 180, 'ACTIVE', '', TIMESTAMP '2024-01-16 11:00:00'),
('ITEM-017', '어댑터', '다양한 전압을 지원하는 범용 어댑터입니다. 해외 여행 시 필수 아이템으로 다양한 국가의 전원에 대응합니다.', 50000, 60, 'ACTIVE', '', TIMESTAMP '2024-01-17 12:00:00'),
('ITEM-018', '블루투스 이어폰', '무선 이어폰으로 자유로운 움직임을 제공합니다. 노이즈 캔슬링과 긴 배터리 수명이 특징입니다.', 110000, 28, 'ACTIVE', '', TIMESTAMP '2024-01-18 13:00:00'),
('ITEM-019', '스마트워치', '건강 관리와 스마트 기능을 갖춘 스마트워치입니다. 심박수 측정, GPS, 알림 등 다양한 기능을 제공합니다.', 245000, 16, 'ACTIVE', '', TIMESTAMP '2024-01-19 14:00:00'),
('ITEM-020', '외장하드', '1TB 용량의 휴대용 외장하드입니다. USB 3.0을 지원하여 빠른 데이터 전송 속도를 제공합니다.', 165000, 24, 'ACTIVE', '', TIMESTAMP '2024-01-20 15:00:00'),
('ITEM-021', 'SSD', '1TB 용량의 고속 SSD입니다. 빠른 부팅 속도와 파일 전송 속도로 컴퓨터 성능을 크게 향상시킵니다.', 220000, 20, 'ACTIVE', '', TIMESTAMP '2024-01-21 16:00:00'),
('ITEM-022', '램', '16GB DDR4 램입니다. 고성능 게이밍과 멀티태스킹에 최적화되어 있습니다.', 185000, 30, 'ACTIVE', '', TIMESTAMP '2024-01-22 17:00:00');
